def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)

    # Compare rows sharing a long prefix. Repeated row patterns can reveal
    # missing cells in the suffix of one of the rows.
    for r1 in range(h):
        for r2 in range(r1 + 1, h):
            a, b = grid[r1], grid[r2]
            k = 0
            while k < w and a[k] == b[k]:
                k += 1
            if k >= max(3, w // 2):
                for c in range(k, w):
                    if a[c] == background and b[c] != background:
                        out[r1][c] = 1
                    elif b[c] == background and a[c] != background:
                        out[r2][c] = 1

            # A near-repeated row can also indicate a missing terminal cell.
            differences = sum(a[c] != b[c] for c in range(w))
            if differences <= max(2, int(w * 0.3)):
                if a[-1] == background and b[-1] != background:
                    out[r1][-1] = 1
                elif b[-1] == background and a[-1] != background:
                    out[r2][-1] = 1

    return out
